import React from 'react';

import { IFund } from '@apps/Finances/@types/funds.types';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

interface IFundListItemProps {
  fund: IFund;
  toolbar?: (fund: IFund) => React.ReactNode;
}

const FundListItem: React.FC<IFundListItemProps> = ({ fund, toolbar }) => {
  return (
    <PohRow>
      <PohCol sm={5}>
        <strong>{fund.name}</strong>
      </PohCol>
      <PohCol sm={2} xs={6}>
        <small>{fund.created_at.toLocaleDateString()}</small>
      </PohCol>
      <PohCol sm={2} xs={6}>
        <small>
          {fund.author.name} {fund.author.surname}
        </small>
      </PohCol>
      <PohCol sm={3} className="text-end">
        {toolbar?.(fund)}
      </PohCol>
    </PohRow>
  );
};

export default FundListItem;
